import{_ as t,c as r,o as i,ag as a}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Funding Certifications Through the Military","description":"","frontmatter":{"title":"Funding Certifications Through the Military"},"headers":[],"relativePath":"general/funding-certifications-through-the-military.md","filePath":"general/funding-certifications-through-the-military.md","lastUpdated":null}'),o={name:"general/funding-certifications-through-the-military.md"};function n(s,e,l,c,h,u){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="funding-certifications-through-the-military" tabindex="-1">Funding Certifications Through the Military <a class="header-anchor" href="#funding-certifications-through-the-military" aria-label="Permalink to &quot;Funding Certifications Through the Military&quot;">​</a></h1><h2 id="funding-certifications" tabindex="-1">Funding Certifications <a class="header-anchor" href="#funding-certifications" aria-label="Permalink to &quot;Funding Certifications&quot;">​</a></h2><h3 id="pearson-vue-government-store" tabindex="-1">Pearson VUE Government Store <a class="header-anchor" href="#pearson-vue-government-store" aria-label="Permalink to &quot;Pearson VUE Government Store&quot;">​</a></h3><p>The Pearson VUE Government Store offers access to discounted certification programs from leading organizations. Below are direct links to some key certifications:</p><p><strong>Main Store Link:</strong> <a href="https://govstore.pearsonvue.com/" target="_blank" rel="noreferrer">Pearson VUE Government Store</a></p><p><strong>Direct Links to Programs:</strong></p><ul><li><p><a href="https://govstore.pearsonvue.com/shop/aws" target="_blank" rel="noreferrer">AWS Certification</a></p></li><li><p><a href="https://govstore.pearsonvue.com/shop/comptia" target="_blank" rel="noreferrer">CompTIA Certification</a></p></li><li><p><a href="https://govstore.pearsonvue.com/shop/microsoft" target="_blank" rel="noreferrer">Microsoft Certification</a></p></li><li><p><a href="https://govstore.pearsonvue.com/shop/cisco" target="_blank" rel="noreferrer">Cisco Certification</a></p></li></ul><ol><li>$4000 a Year for SANS Use your Credentialing Assistance (CA) to fund SANS Training. Follow the <a href="http://url.irregular.chat/msuite" target="_blank" rel="noreferrer">Guide Here</a>.</li></ol><p>This funding counts against your tuition assistance ($4000). The guide helps reduce the SANS price to meet the annual CA allotment.</p><h3 id="sof-education-program-sep-funds-guide" tabindex="-1">SOF Education Program (SEP) Funds Guide <a class="header-anchor" href="#sof-education-program-sep-funds-guide" aria-label="Permalink to &quot;SOF Education Program (SEP) Funds Guide&quot;">​</a></h3><p><a href="https://u.pcloud.link/publink/show?code=XZ0frk0ZchOJr4ELEVkiFyB7Ic45CmhSpaEk" target="_blank" rel="noreferrer">Download/View Guide</a></p><p>SEP offers up to $10,000 per fiscal year, separate from Tuition Assistance (TA) or Credentialing Assistance (CA). This funding addresses specific knowledge gaps in special operations roles, supporting professional development without duplicating existing programs. SEP is not for degree programs or large group education but focuses on individual needs in special operations.</p><ul><li><p>Requires submission of forms like SF-182.</p></li><li><p>Must comply with specific criteria, such as no planned separation within 18 months.</p></li><li><p>Requests involve Company and Battalion Commander approval, followed by SWCS signatures.</p></li></ul><p>For more details, contact the Education Office.</p><h3 id="cert-cheatsheets-and-resources" tabindex="-1">Cert Cheatsheets and Resources <a class="header-anchor" href="#cert-cheatsheets-and-resources" aria-label="Permalink to &quot;Cert Cheatsheets and Resources&quot;">​</a></h3><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><p><a href="https://forum.irregularchat.com/t/community-links-to-chats-and-services/229#p-598-tech-8" target="_blank" rel="noreferrer">Join the Signal Group</a> (Login Required) for discussions on certifications and training, especially tech-related ones.</p></li><li><p><a href="https://cheatsheetseries.owasp.org/" target="_blank" rel="noreferrer">OWASP Cheat Sheet Series</a></p></li><li><p><a href="https://www.isc2.org/Certifications/CC" target="_blank" rel="noreferrer">Free ISC2 Certification Opportunity</a></p></li><li><p><a href="https://github.com/devanshbatham/Awesome-Bugbounty-Writeups" target="_blank" rel="noreferrer">Bug Bounty CTF Writeups</a></p></li><li><p><a href="https://github.com/0xsyr0/OSCP" target="_blank" rel="noreferrer">OSCP Resources</a></p></li></ul><h3 id="sans-certs" tabindex="-1">SANS Certs <a class="header-anchor" href="#sans-certs" aria-label="Permalink to &quot;SANS Certs&quot;">​</a></h3><p>Looking for SANS funding? Check out the page for <a href="/general/credentialing-assistance.html">Assistance</a>.</p><h3 id="comptia-certifications" tabindex="-1">CompTIA Certifications <a class="header-anchor" href="#comptia-certifications" aria-label="Permalink to &quot;CompTIA Certifications&quot;">​</a></h3><p>CompTIA certifications are widely recognized in the IT industry and can validate your skills and boost your career. Here’s how you can pursue them with funding assistance:</p><ul><li><p>Access online training modules available on the <a href="https://usarmy.percipio.com/" target="_blank" rel="noreferrer">Army eLearning Website</a>. These courses range from foundational to advanced knowledge necessary for the CompTIA exams.</p></li><li><p>After completing your training, navigate to the ACTMS website. This platform allows you to upload routine cyber awareness training certificates and provides a section for token requests for certifications.</p></li><li><p>Scroll to the bottom of the page to find the &quot;Token Request&quot; section. Fill out the necessary information detailing your certification needs.</p></li><li><p>Submit your request and await confirmation. Once approved, you will receive a voucher code to schedule your certification exam.</p></li></ul><p><strong>Note:</strong> Processing times can vary (up to 6 months), so plan accordingly.</p><h3 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h3><p><strong>Q: Is this funding separate from the Credentialing Assistance program?</strong></p><p><strong>A: Yes.</strong> The funding for CompTIA certifications comes from a different source and does not impact the finances allocated for the Credentialing Assistance program. These are distinct funding pots, each with its application process and criteria.</p>',26)])])}const f=t(o,[["render",n]]);export{d as __pageData,f as default};
